import pandas as pd

PAIRS = {"bàn": ("FTHG", "FTAG"), "cú sút": ("HS", "AS"),
         "sút trúng đích": ("HST", "AST"), "phạt góc": ("HC", "AC"),
         "phạm lỗi": ("HF", "AF"), "thẻ vàng": ("HY", "AY"), "thẻ đỏ": ("HR", "AR")}

def dispersion(df):
    """var/mean: gần 1 thì gần Poisson; lớn hơn hẳn 1 là phân tán quá mức."""
    rows = []
    for name, (h, a) in PAIRS.items():
        for unit, s in [("đội nhà", df[h]), ("đội khách", df[a]), ("cả trận", df[h] + df[a])]:
            s = s.dropna().astype(float)
            rows.append({"variable": name, "unit": unit, "mean": s.mean(),
                         "var_over_mean": s.var() / s.mean()})
    return pd.DataFrame(rows)

df = pd.read_parquet("data/clean/matches.parquet")
stats = df[df.season >= "2000/01"]       # cú sút, thẻ có từ mùa này
dispersion(stats).to_csv("results/eda_dispersion.csv", index=False)

