import numpy as np
import pandas as pd

def llr_weights(p0, p1):
    return np.log(p1 / p0), np.log((1 - p1) / (1 - p0))   # cộng khi x = 1, x = 0

def bernoulli_cusum(x, p0, delta, h):
    w = {"giảm": llr_weights(p0, p0 - delta), "tăng": llr_weights(p0, p0 + delta)}
    s = {"giảm": 0.0, "tăng": 0.0}
    last_zero = {"giảm": -1, "tăng": -1}
    path, alarms = np.zeros((len(x), 2)), []
    for t, xt in enumerate(x):
        for side, (w1, w0) in w.items():
            s[side] = max(0.0, s[side] + (w1 if xt == 1 else w0))  # sàn 0
            if s[side] == 0.0:
                last_zero[side] = t
        path[t] = s["giảm"], s["tăng"]
        for side in ("giảm", "tăng"):
            if s[side] > h:                                         # báo
                alarms.append({"t": t, "side": side, "change_t": last_zero[side] + 1})
                s = {"giảm": 0.0, "tăng": 0.0}                      # đặt cả hai về 0
                last_zero = {"giảm": t, "tăng": t}
                break
    return pd.DataFrame(path, columns=["s_down", "s_up"]), alarms

import numpy as np

def bounds(alpha, beta):
    return np.log(beta / (1 - alpha)), np.log((1 - beta) / alpha)

def sprt(x, p0, p1, alpha=0.05, beta=0.10):
    a, b = bounds(alpha, beta)
    step = np.where(np.asarray(x) == 1, np.log(p1 / p0),
                    np.log((1 - p1) / (1 - p0)))
    llr = np.cumsum(step)                        # Λ sau mỗi trận
    hit = np.flatnonzero((llr >= b) | (llr <= a))
    if len(hit) == 0:
        return {"decision": "chưa quyết", "n": len(llr), "llr": llr}
    n = hit[0]
    return {"decision": "H1" if llr[n] >= b else "H0", "n": n + 1, "llr": llr}

def phase1_params(df, first="2016/17", last="2018/19"):
    ph = df[df.season.between(first, last)]
    p0, draw = ph.home_win.mean(), (ph.FTR == "D").mean()
    return p0, draw, (1 - draw) / 2              # p1: hết lợi thế sân nhà
